<template>
  <div class="p-6 space-y-6 bg-slate-50/50 min-h-full">
    <div class="flex flex-col lg:flex-row lg:items-end justify-between gap-4"><div class="flex items-center gap-3"><div class="h-11 w-11 rounded-2xl bg-emerald-100 text-emerald-700 flex items-center justify-center"><History class="h-6 w-6" /></div><div><h1 class="text-2xl font-black tracking-tight text-slate-900">Riwayat Pergerakan Stok</h1><p class="text-sm text-slate-500">Pantau seluruh perubahan stok {{ currentBranchName }} secara terpusat.</p></div></div><Button variant="outline" class="rounded-xl" @click="warehouseStore.fetchLogs()"><RefreshCw class="w-4 h-4 mr-2" /> Segarkan</Button></div>
    <div class="grid grid-cols-1 sm:grid-cols-3 gap-4"><Card v-for="stat in stats" :key="stat.label" class="border-none shadow-sm rounded-2xl"><CardContent class="p-5 flex items-center justify-between"><div><p class="text-xs font-bold text-slate-400 uppercase tracking-wider">{{ stat.label }}</p><p class="text-2xl font-black mt-1" :class="stat.color">{{ stat.value.toLocaleString('id-ID') }}</p></div><component :is="stat.icon" class="w-7 h-7 opacity-30" :class="stat.color" /></CardContent></Card></div>
    <Card class="border-none shadow-sm rounded-2xl"><CardContent class="p-5 space-y-4"><div class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-3"><div class="relative lg:col-span-2"><Search class="absolute left-3 top-3 w-4 h-4 text-slate-400" /><Input v-model="filters.search" class="pl-9 rounded-xl" placeholder="Cari produk, SKU, sumber, petugas..." /></div><select v-model="filters.type" class="h-10 rounded-xl border border-slate-200 px-3 text-sm bg-white"><option value="">Semua tipe</option><option v-for="type in types" :key="type" :value="type">{{ type }}</option></select><Input v-model="filters.from" type="date" class="rounded-xl" /><Input v-model="filters.to" type="date" class="rounded-xl" /></div><div class="flex items-center justify-between gap-3 text-xs text-slate-500"><span>Menampilkan <b class="text-slate-800">{{ filteredLogs.length }}</b> dari {{ warehouseStore.logs.length }} aktivitas</span><Button v-if="hasFilters" variant="ghost" size="sm" class="rounded-lg text-emerald-700" @click="resetFilters"><X class="w-4 h-4 mr-1" /> Reset filter</Button></div></CardContent></Card>
    <Card class="border-none shadow-sm rounded-2xl overflow-hidden"><CardContent class="p-0 overflow-x-auto"><table class="w-full text-sm text-left"><thead class="bg-slate-50 border-b border-slate-100 text-[10px] font-black text-slate-400 uppercase tracking-widest"><tr><th class="px-6 py-4">Waktu</th><th class="px-6 py-4">Produk</th><th class="px-6 py-4">Tipe</th><th class="px-6 py-4">Sumber / Keterangan</th><th class="px-6 py-4">Diproses Oleh</th><th class="px-6 py-4 text-right">Jumlah</th></tr></thead><tbody class="divide-y divide-slate-100"><tr v-for="log in filteredLogs" :key="log.id" class="hover:bg-slate-50/80"><td class="px-6 py-4 whitespace-nowrap text-slate-500">{{ formatDate(log.created_at) }}</td><td class="px-6 py-4"><p class="font-bold text-slate-800">{{ log.product?.name || log.product_name || '-' }}</p><p class="text-xs text-slate-400">{{ log.product?.sku || log.sku || '' }}</p></td><td class="px-6 py-4"><span class="px-2.5 py-1 rounded-full text-[10px] font-black" :class="typeClass(log.type)">{{ log.type || '-' }}</span></td><td class="px-6 py-4 text-slate-600">{{ log.source || log.description || '-' }}</td><td class="px-6 py-4 text-slate-600">{{ displayUser(log.processed_by) }}</td><td class="px-6 py-4 text-right font-black" :class="isOut(log) ? 'text-rose-600' : 'text-emerald-600'">{{ isOut(log) ? '-' : '+' }}{{ Number(log.quantity || 0).toLocaleString('id-ID') }}</td></tr><tr v-if="!filteredLogs.length"><td colspan="6" class="px-6 py-16 text-center text-slate-400"><History class="w-10 h-10 mx-auto mb-3 opacity-30" /><p class="font-semibold">Tidak ada riwayat sesuai filter.</p></td></tr></tbody></table></CardContent></Card>
  </div>
</template>
<script setup lang="ts">
import { computed, onMounted, reactive, watch } from 'vue'
import { History, Search, RefreshCw, X, ArrowDownToLine, ArrowUpFromLine, Activity } from 'lucide-vue-next'
import { Card, CardContent } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { useWarehouseStore } from '@/stores/warehouse'
import { useMasterDataStore } from '@/stores/masterData'
const warehouseStore = useWarehouseStore(); const masterDataStore = useMasterDataStore()
const filters = reactive({ search: '', type: '', from: '', to: '' })
const currentBranchName = computed(() => masterDataStore.branches.find((b) => b.id === masterDataStore.selectedWarehouseBranchId)?.name || 'cabang terpilih')
const types = computed(() => [...new Set(warehouseStore.logs.map((l) => l.type).filter(Boolean))] as string[])
const normalized = (v: any) => String(v ?? '').toLowerCase()
const isOut = (log: any) => String(log?.type || '').toUpperCase() === 'OUT' || (!log?.type && /out|keluar|issue|deduct|sale/i.test(String(log?.source || '')))
const displayUser = (v: any) => typeof v === 'object' ? [v?.first_name, v?.last_name].filter(Boolean).join(' ') || '-' : v || '-'
const filteredLogs = computed(() => warehouseStore.logs.filter((log) => { const date = String(log.created_at || '').slice(0, 10); const text = [log.product?.name, log.product?.sku, log.product_name, log.sku, log.type, log.source, log.description, displayUser(log.processed_by)].map(normalized).join(' '); return (!filters.search || text.includes(normalized(filters.search))) && (!filters.type || log.type === filters.type) && (!filters.from || date >= filters.from) && (!filters.to || date <= filters.to) }))
const stats = computed(() => [{ label: 'Aktivitas', value: filteredLogs.value.length, color: 'text-slate-700', icon: Activity }, { label: 'Stok masuk', value: filteredLogs.value.filter((l) => !isOut(l)).reduce((n, l) => n + Number(l.quantity || 0), 0), color: 'text-emerald-600', icon: ArrowDownToLine }, { label: 'Stok keluar', value: filteredLogs.value.filter(isOut).reduce((n, l) => n + Number(l.quantity || 0), 0), color: 'text-rose-600', icon: ArrowUpFromLine }])
const hasFilters = computed(() => Object.values(filters).some(Boolean)); const formatDate = (v: any) => v ? new Date(v).toLocaleString('id-ID', { dateStyle: 'medium', timeStyle: 'short' }) : '-'; const typeClass = (type: any) => isOut({ type }) ? 'bg-rose-50 text-rose-700' : 'bg-emerald-50 text-emerald-700'; const resetFilters = () => Object.assign(filters, { search: '', type: '', from: '', to: '' })
watch(() => masterDataStore.selectedWarehouseBranchId, () => warehouseStore.fetchLogs()); onMounted(() => { masterDataStore.fetchBranches(); warehouseStore.fetchLogs() })
</script>
